fn double_all(v: &mut Vec[Int]) -> Unit {
  var i = 0;
  while i < v.len() {
    v[i] = v[i] * 2;
    i = i + 1;
  }
}

fn summarize(v: &Vec[Int]) -> Str {
  var total = 0;
  var i = 0;
  while i < v.len() {
    total = total + v[i];
    i = i + 1;
  }
  return "sum: " + total + ", len: " + v.len();
}

fn main() -> Int {
  var data = Vec[Int]();
  data.push(1);
  data.push(2);
  data.push(3);
  let s1 = summarize(&data);
  double_all(&mut data);
  let s2 = summarize(&data);
  return data[0];
}
